def fizzbuzz(n: int) -> list[str]:
    """
    Devuelve una lista de strings del 1 al n, donde:
      - Multiplos de 3 son 'Fizz'
      - Multiplos de 5 son 'Buzz'
      - Multiplos de 3 y 5 son 'FizzBuzz'
      - Los demás son los números como string.
    """
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

def a_romano(n: int) -> str:
    """Convierte un entero entre 1 y 3999 a su representación en números romanos usando notación sustractiva."""
    if n < 1 or n > 3999:
        raise ValueError("El número debe estar entre 1 y 3999.")

    if n == 0:
        return "0"

    # Definición de los valores de los símbolos
    values = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1]
    symbols = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"]

    # Construir la representación romana
    result = []
    for i in range(len(values)):
        while n >= values[i]:
            result.append(symbols[i])
            n -= values[i]

    return "".join(result)

def mayor_racha(lista):
    """
    Encuentra la racha más larga de elementos consecutivos iguales
    y devuelve la tupla (elemento, longitud).
    Si hay empate, devuelve la primera tupla encontrada.
    Si la lista está vacía, devuelve None.
    """
    if not lista:
        return None

    max_racha = 1
    max_elemento = lista[0]
    racha_actual = 1

    for i in range(1, len(lista)):
        if lista[i] == max_elemento:
            racha_actual += 1
        else:
            if racha_actual > max_racha:
                max_racha = racha_actual
                max_elemento = lista[i]
            racha_actual = 1

    # Verificar el último segmento
    if racha_actual > max_racha:
        max_racha = racha_actual
        max_elemento = lista[-1]

    return (max_elemento, max_racha)

def a_camel(s: str) -> str:
    """Convierte un texto en snake_case a camelCase.

    La primera palabra en minúscula y las siguientes con la inicial en mayúscula,
    sin guiones bajos.

    Args:
        s: El texto a convertir.

    Returns:
        El texto convertido en camelCase.
    """
    words = s.split()
    result = []
    for word in words:
        if word:
            if len(word) == 1:
                result.append(word)
            else:
                result.append(word[0].upper() + word[1:])
    return " ".join(result)

def primos(n: int) -> list[int]:
    """Devuelve la lista ordenada de todos los números primos menores o iguales a n."""
    if n < 2:
        return []

    primos = []
    for i in range(2, n + 1):
        es_primo = True
        for j in range(2, int(i**0.5) + 1):
            if i % j == 0:
                es_primo = False
                break
        if es_primo:
            primos.append(i)

    return primos

def comprimir(s: str) -> str:
    """
    Aplica codificación por repeticiones a una cadena de caracteres.

    Ejemplo: 'aaabb' -> 'a3b2'

    Si la versión comprimida es igual o más larga que la original,
    se devuelve la versión original sin cambios.

    Args:
        s: La cadena de caracteres a comprimir.

    Returns:
        La cadena comprimida si es más corta que la original,
        o la cadena original si no lo es.
    """
    if not s:
        return s

    # Contar repeticiones de cada carácter
    counts = {}
    for char in s:
        counts[char] = counts.get(char, 0) + 1

    # Construir la cadena comprimida
    result = ""
    for char, count in counts.items():
        if count > 1:
            result += char + str(count)
        else:
            result += char

    # Verificar si la versión comprimida es más corta
    if len(result) <= len(s):
        return result
    else:
        return s

def balanceado(s: str) -> bool:
    """
    Verifica si los parentesis, corchetes y llaves del texto están correctamente
    balanceados y anidados.

    Args:
        s: La cadena de texto a verificar.

    Returns:
        True si los paréntesis, corchetes y llaves están balanceados,
        False en caso contrario.
    """
    # Contadores para cada tipo de paréntesis
    open_brackets = 0
    close_brackets = 0
    open_parens = 0
    close_parens = 0

    for char in s:
        if char == '(':
            open_brackets += 1
            open_parens += 1
        elif char == ')':
            close_brackets += 1
            close_parens += 1
        elif char == '[':
            open_brackets += 1
        elif char == ']':
            close_brackets += 1
        elif char == '{':
            open_brackets += 1
            open_parens += 1
        elif char == '}':
            close_brackets += 1
            close_parens += 1

        # Verificar balanceo en cada tipo de paréntesis
        if open_brackets > 0 and close_brackets > 0:
            if open_brackets != close_brackets:
                return False
        if open_parens > 0 and close_parens > 0:
            if open_parens != close_parens:
                return False

    # Verificar que no haya paréntesis cerrados sin abrir
    if open_brackets > 0 or open_parens > 0:
        return False

    return True

def fusionar(intervalos: list[tuple[int, int]]) -> list[tuple[int, int]]:
    """
    Recibe una lista de tuplas (inicio, fin) y devuelve la lista de intervalos
    fusionados, ordenados por inicio. Dos intervalos se fusionan si se tocan,
    es decir, si el inicio del segundo es igual o igual al fin del primero.

    Ejemplo:
        fusionar([(1, 3), (3, 5), (5, 7)]) -> [(1, 7)]
    """
    if not intervals:
        return []

    result = []
    for inicio, fin in intervals:
        if not result:
            result.append((inicio, fin))
        elif inicio <= result[-1][1]:
            result[-1] = (result[-1][0], max(result[-1][1], fin))
        else:
            result.append((inicio, fin))

    return result

def anidar(plano: dict) -> dict:
    """
    Recursivamente convierte un dict de claves con puntos en un dict anidado.

    Ejemplo:
        {'a.b': 1} -> {'a': {'b': 1}}
        {'a.b.c': 2} -> {'a': {'b': {'c': 2}}}
        {'a.b.c.d': 3} -> {'a': {'b': {'c': {'d': 3}}}}
    """
    if not plano:
        return {}

    # Recorrer cada par clave-valued
    for clave, valor in plano.items():
        # Si la clave es un punto (o más puntos), recursivamente anidar
        if '.' in clave:
            clave_anidada = clave.split('.')
            # Recursivamente anidar la parte de la clave
            clave_anidada = anidar(clave_anidada)
            # Construir el nuevo dict con la clave anidada
            plano[clave_anidada] = valor
        else:
            # Si la clave no tiene puntos, es una clave simple
            plano[clave] = valor

    return plano


