def formatear_bytes(n: int) -> str:
    """Convierte un número de bytes a texto legible usando múltiplos de 1024.

    Unidades: B, KB, MB, GB.
    B va sin decimales, KB, MB, GB van con decimales.

    Args:
        n: Número de bytes a convertir.

    Returns:
        String formateada como 'n.B' o 'n.0 KB', 'n.0 MB', etc.
    """
    if n < 0:
        raise ValueError("El número de bytes debe ser positivo.")

    if n == 0:
        return "0 B"

    if n < 1024:
        return f"{n} B"

    if n < 1024 * 1024:
        return f"{n / 1024:.1f} KB"

    if n < 1024 * 1024 * 1024:
        return f"{n / (1024 * 1024):.1f} MB"

    return f"{n / (1024 * 1024 * 1024):.1f} GB"

def parsear_query(s: str) -> dict:
    """
    Convierte un query string tipo 'a=1&b=2' en un dict {'a':'1','b':'2'}.
    Una clave sin valor ('c=') queda con string vacio.
    String vacio devuelve dict vacio.
    """
    if not s:
        return {}
    result = {}
    for part in s.split("&"):
        if "=" in part:
            key, value = part.split("=", 1)
            result[key] = value
    return result

def contar_islas(grid: list[list[int]]) -> int:
    """
    Recibe una matriz de 0 y 1 y devuelve el número de grupos de 1 conectados.
    Dos celdas son conectadas si comparten un lado (arriba, abajo, izquierda, derecha).

    Args:
        grid: Una matriz de listas de 0 y 1.

    Returns:
        El número de grupos de 1 conectados.
    """
    if not grid:
        return 0

    rows = len(grid)
    cols = len(grid[0])

    def is_neighbor(r1, c1, r2, c2):
        """Verifica si dos celdas son vecinos (comparten un lado)."""
        return abs(r1 - r2) + abs(c1 - c2) == 1

    def is_same_value(r1, c1, r2, c2):
        """Verifica si dos celdas tienen el mismo valor."""
        return grid[r1][c1] == grid[r2][c2]

    visited = [[False] * cols for _ in range(rows)]
    count = 0

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and not visited[r][c]:
                count += 1
                visited[r][c] = True
                # Recursión: visitar vecinos
                if is_neighbor(r, c, r + 1, c):
                    visited[r + 1][c] = True
                if is_neighbor(r, c, r - 1, c):
                    visited[r - 1][c] = True
                if is_neighbor(r, c, r, c + 1):
                    visited[r][c + 1] = True
                if is_neighbor(r, c, r, c - 1):
                    visited[r][c - 1] = True

    return count

